const test = require('node:test'), assert = require('node:assert/strict');
const { decodeGifFrames } = require('../gif.js');

// 4 x 4 GIF89a, 3 frames, generated by hand so every rule is exercised:
//   frame 1: 40 ms, full picture, INTERLACED rows, no transparency
//   frame 2: 50 ms, 2 x 2 sub-rectangle at (1,1), transparent index 0, disposal 2 (clear the rectangle afterwards)
//   frame 3: 60 ms, full picture, transparent index 0, drawn over the cleared rectangle
// Palette: W white, R red, G green, B blue, '.' transparent.
const FIXTURE = Buffer.from('R0lGODlhBAAEAPEAAP////8AAAD/AAAA/yH5BAAEAAAALAAAAAAEAAQAQAIHTIQyO+A3CgAh+QQJBQAAACwBAAEAAgACAAACAwwgBQAh+QQBBgAAACwAAAAABAAEAAACBxwMkcICNwoAOw==', 'base64');
const EXPECTED = [
  ['RRGG', 'BBWW', 'GGBB', 'WRGB'],
  ['RRGG', 'BRWW', 'GGGB', 'WRGB'],
  ['BRBG', 'BR.R', 'GGGG', 'WRBB'],
];
const COLOURS = { '255,255,255': 'W', '255,0,0': 'R', '0,255,0': 'G', '0,0,255': 'B' };

const toArrayBuffer = b => new Uint8Array(b).buffer;   // a copy, so pooled Buffers do not leak into the decoder
const asPicture = (rgba, w, h) => {
  const rows = [];
  for (let r = 0; r < h; r++) {
    let s = '';
    for (let c = 0; c < w; c++) {
      const i = (r * w + c) * 4;
      s += rgba[i + 3] === 0 ? '.' : COLOURS[[rgba[i], rgba[i + 1], rgba[i + 2]].join(',')] || '?';
    }
    rows.push(s);
  }
  return rows;
};

test('decodes size, frame count and delays', () => {
  const g = decodeGifFrames(toArrayBuffer(FIXTURE));
  assert.equal(g.width, 4); assert.equal(g.height, 4);
  assert.deepEqual(g.frames.map(f => f.ms), [40, 50, 60]);
  for (const f of g.frames) assert.equal(f.rgba.length, 4 * 4 * 4);
});

test('composes every frame exactly as the GIF rules require', () => {
  const g = decodeGifFrames(toArrayBuffer(FIXTURE));
  g.frames.forEach((f, k) => assert.deepEqual(asPicture(f.rgba, 4, 4), EXPECTED[k], `frame ${k + 1}`));
});

test('frames are Uint8ClampedArray of width * height * 4, ready for ImageData in the page', () => {
  const g = decodeGifFrames(toArrayBuffer(FIXTURE));
  for (const f of g.frames) { assert.ok(f.rgba instanceof Uint8ClampedArray); assert.equal(f.rgba.length, g.width * g.height * 4); }
});

test('a truncated file keeps the frames that were complete and does not throw', () => {
  const cut = FIXTURE.subarray(0, FIXTURE.length - 40);   // cuts into the last frame
  const g = decodeGifFrames(toArrayBuffer(cut));
  assert.ok(g.frames.length >= 2, 'frames before the damage are kept');
  assert.deepEqual(asPicture(g.frames[0].rgba, 4, 4), EXPECTED[0]);
});

test('input that is not a GIF is rejected with a clear error', () => {
  assert.throws(() => decodeGifFrames(toArrayBuffer(Buffer.from('this is a text file, not an image'))), /not a GIF/);
  assert.throws(() => decodeGifFrames(new ArrayBuffer(0)), /not a GIF/);
});

test('a GIF with no image data is rejected', () => {
  const header = Buffer.concat([Buffer.from('GIF89a'), Buffer.from([4, 0, 4, 0, 0, 0, 0]), Buffer.from([0x3B])]);
  assert.throws(() => decodeGifFrames(toArrayBuffer(header)), /no frames/);
});

// 2 x 2 GIF: red, then green with disposal 3 (restore the picture from before that frame), then a frame whose
// transparent pixels must therefore show red, not green.
const FIXTURE_DISPOSAL3 = Buffer.from('R0lGODlhAgACAPEAAP////8AAAD/AAAA/yH5BAADAAAALAAAAAACAAIAAAICjFMAIfkEDAQAAAAsAAAAAAIAAgAAAgKUVQAh+QQBBQAAACwAAAAAAgACAAACAsRcADs=', 'base64');

test('disposal method 3 restores the picture from before the frame that asked for it', () => {
  const g = decodeGifFrames(toArrayBuffer(FIXTURE_DISPOSAL3));
  assert.deepEqual(g.frames.map(f => f.ms), [30, 40, 50]);
  assert.deepEqual(asPicture(g.frames[1].rgba, 2, 2), ['GG', 'GG']);
  assert.deepEqual(asPicture(g.frames[2].rgba, 2, 2), ['RB', 'RB'], 'transparent pixels show the restored red');
});
